from django.db import migrations, models


def migrar_facultades(apps, schema_editor):
    Usuario = apps.get_model("users", "Usuario")
    Facultad = apps.get_model("deportes", "Facultad")
    database = schema_editor.connection.alias

    for usuario in Usuario.objects.using(database).all().iterator():
        nombre = " ".join((usuario.facultad or "").split()).upper()
        if not nombre:
            continue

        facultad = Facultad.objects.using(database).filter(nombre=nombre).first()
        if facultad is None:
            sigla_base = "".join(palabra[0] for palabra in nombre.split())[:16] or "FAC"
            sigla = sigla_base
            sufijo = 1
            while Facultad.objects.using(database).filter(sigla=sigla).exists():
                sufijo_texto = str(sufijo)
                sigla = f"{sigla_base[:20 - len(sufijo_texto)]}{sufijo_texto}"
                sufijo += 1
            facultad = Facultad.objects.using(database).create(
                nombre=nombre,
                sigla=sigla,
            )
        usuario.facultad_nueva_id = facultad.pk
        usuario.save(update_fields=["facultad_nueva"], using=database)


